% ============================================================
% style.tex - Shared preamble, macros and layout definitions
% Adapted from DSE-latex/Maths for HKTA THMSS F.1 First Test
% ============================================================

\usepackage[a4paper,top=25mm,bottom=22mm,left=25mm,right=18mm,headsep=5mm,footskip=0mm]{geometry}
\usepackage{tikz}
\usetikzlibrary{calc}
\usepackage{array}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\usepackage{enumitem}
\usepackage{fancyhdr}
\usepackage{helvet}
\usepackage{mathptmx}  % Times New Roman for text and math
\usepackage{pgfcore}
\usepackage{atbegshi}  % Better page shipout control than everypage

% Default font is Times New Roman (will be overridden for cover page)

% ---- Colours ----
\definecolor{stripeblack}{gray}{0.0}
\definecolor{rulegray}{gray}{0.6}

% ---- Centralised customisation settings ----
% All paper-specific text and metadata live in config.tex.
\input{config}

% ------------------------------------------------------------
% Top-left slanted (parallelogram) label + thin left vertical rule
% The strip is WHITE with a thin black border; text is black.
% ------------------------------------------------------------
\newcommand{\DrawCornerStrip}{%
  \begin{tikzpicture}[remember picture,overlay]
    % Slanted black line
    \draw[black,line width=1.1mm]
      ([xshift=57mm,yshift=-4mm]current page.north west) --
      ([xshift=4mm,yshift=-57mm]current page.north west);

    % Black text on the slanted strip
    \node[black,font=\bfseries\small,anchor=west]
      at ([xshift=8mm,yshift=-25mm]current page.north west)
      {\begin{tabular}{@{}l@{}}\PaperCode\\\PaperSubjLine \vspace{2mm} \\  \textmd{\PaperType}\end{tabular}};
  \end{tikzpicture}%
}

% ------------------------------------------------------------
% Answer space: n ruled lines
% ------------------------------------------------------------
\newcommand{\answerlines}[1]{%
  \par\vspace{2mm}
  \foreach \i in {1,...,#1}{%
    \vspace{7mm}\noindent\rule{\linewidth}{0.2pt}\par
  }%
}

% ------------------------------------------------------------
% Question header: number is inline with the question stem, and the
% total marks are shown in parentheses next to the question number.
%   #1 = question number
%   #2 = total marks for the question
% ------------------------------------------------------------
\newcommand{\question}[2]{%
  \vspace{5mm}%
  \noindent\textbf{#1.}\hspace{1em}\textbf{(#2 marks)}\hspace{1em}\ignorespaces
}

% ------------------------------------------------------------
% Per-item marks: pushed to the right margin at the end of an item
% (kept for flexibility; not used in the F.1 First Test)
% ------------------------------------------------------------
\newcommand{\qmarks}[1]{\nobreak\hfill\textnormal{(#1 marks)}}

% ------------------------------------------------------------
% Section header
% ------------------------------------------------------------
\newcommand{\sectionheader}[1]{%
  \vspace*{0mm}
  \noindent\textbf{Section #1}\par
  \vspace{1mm}
}

% ------------------------------------------------------------
% Page footer with page number and margin frame
% ------------------------------------------------------------
\pagestyle{fancy}
\fancyhf{}
\renewcommand{\headrulewidth}{0pt}
\fancyfoot[C]{\hspace*{3.5mm}\fontsize{12pt}{12pt}\selectfont\thepage}
\fancyfoot[L]{\hspace*{3.5em}\fontsize{8pt}{9pt}\selectfont \PaperFooterCode}
\fancyheadoffset[L]{22mm}
\fancyfootoffset[L]{22mm}

% Count physical sheets independently of \value{page}, because the
% titlepage environment resets the page counter to 1 (so the cover and the
% first content page both report page=1). Sheet 1 = cover, sheet 2+ = content.
\newcounter{physsheet}
\setcounter{physsheet}{0}
\AtBeginShipout{%
  \stepcounter{physsheet}%
  \ifnum\value{physsheet}>1\relax
    \AtBeginShipoutUpperLeft{%
      \begin{tikzpicture}[remember picture,overlay]
        % Draw the rectangular frame - on ALL content pages (sheet > 1)
        \draw[black,line width=0.4pt]
          ([xshift=17mm,yshift=-22mm]current page.north west) rectangle
          ([xshift=-17mm,yshift=30mm]current page.south east);
        % "Answers written in the margins will not be marked." notice
        % running just inside the left, right and bottom borders.
        \node[black,font=\fontsize{10pt}{10pt}\selectfont,rotate=90,anchor=center]
          at ([xshift=13mm]current page.west)
          {\MarginNotice};
        \node[black,font=\fontsize{10pt}{10pt}\selectfont,rotate=90,anchor=center]
          at ([xshift=-13mm]current page.east)
          {\MarginNotice};
        \node[black,font=\fontsize{10pt}{10pt}\selectfont,anchor=center]
          at ([xshift=-50mm,yshift=25mm]current page.south)
          {\MarginNotice};
      \end{tikzpicture}%
    }%
  \fi
}

% Cover page style (different margins: left=0mm, right=12mm)
\fancypagestyle{cover}{%
  \fancyhf{}
  \renewcommand{\headrulewidth}{0pt}
  \fancyfoot[C]{\hspace*{6mm}\fontsize{12pt}{12pt}\selectfont\thepage}
  \fancyfoot[L]{\hspace*{5.5em}\fontsize{8pt}{9pt}\selectfont \PaperFooterCode}
  \fancyheadoffset[L]{0mm}
  \fancyfootoffset[L]{0mm}
}

% ============================================================
% config.tex - CENTRALISED CUSTOMISATION SETTINGS
% ------------------------------------------------------------
% Edit everything paper-specific here. Nothing else should need
% to change from paper to paper (except the candidate number,
% which is filled in by hand, and the questions in questions/).
% ============================================================

% ---- Paper metadata (corner strip, footer, running heads) ----
\newcommand{\PaperYear}{2024}
\newcommand{\PaperCode}{MATH S.1}
\newcommand{\PaperSubjLine}{2024--2025}
\newcommand{\PaperType}{FIRST TEST}
\newcommand{\PaperTotalMarks}{60}
\newcommand{\PaperTime}{40 minutes}

% ---- Marks table ----
% Inclusive question-number range, displayed total, and row-height multiplier.
% Increase \MarksTableRowHeight for fewer rows; decrease it for larger ranges.
\newcommand{\MarksTableFirstQuestion}{1}
\newcommand{\MarksTableLastQuestion}{9}
\newcommand{\MarksTableTotal}{60}
\newcommand{\MarksTableRowHeight}{2}

% Code printed in the bottom-left of every page.
\newcommand{\PaperFooterCode}{HKTA THMSS MATH S.1 FT 2024}

% ---- Cover page text ----
\newcommand{\CoverAuthority}{HONG KONG TAOIST ASSOCIATION --- TANG HIN MEMORIAL SECONDARY SCHOOL}
\newcommand{\CoverExamName}{SECONDARY 1 FIRST TEST 2024--2025}
\newcommand{\CoverTitle}{MATHEMATICS \\ FIRST TEST}
\newcommand{\CoverSubtitle}{Question-Answer Book}
\newcommand{\CoverLanguageNote}{This paper must be answered in English}

% ---- Cover page instructions ----
\newcommand{\CoverInstrHeading}{INSTRUCTIONS}
% The full instruction list. Edit the wording of any item here.
\newcommand{\CoverInstructions}{%
  \begin{enumerate}[label={(\arabic*)},itemsep=12pt,topsep=0pt,parsep=0pt,labelsep=1.6em]
    \item This paper consists of TWO sections, A and B.
    \item This paper consists of 9 pages.
    \item Attempt ALL questions in this paper. Write your answers in the spaces provided in this Question-Answer Book.
    \item Unless otherwise specified, all working must be clearly shown.
    \item The diagrams in this paper are not necessarily drawn to scale.
    \item Calculator is not allowed.
  \end{enumerate}%
}

% ---- Candidate number box label (the box itself is filled by hand) ----
\newcommand{\CoverCandidateLabel}{Class Number}

% ---- Copyright notice ----
\newcommand{\CoverCopyright}{%
  \textcopyright\ HKTA Tang Hin Memorial Secondary School. All rights reserved 2024.%
}

% ---- Margin notice, repeated on the three borders of content pages ----
\newcommand{\MarginNotice}{Answers written in the margins will not be marked.}

% ============================================================
% main.tex - Top-level driver file
% Compile with: pdflatex -interaction=nonstopmode main.tex
% ============================================================

\documentclass[11pt,a4paper]{article}

\input{style}

\begin{document}

  % Front cover (includes candidate number)
  \input{cover}

  % The titlepage environment resets the page counter to 1 on \end, so the
  % first content page would reuse the cover's number. Force content to start
  % at page 2.
  \setcounter{page}{2}

  % Questions and answer lines
  \input{content}

\end{document}

% ============================================================
% cover.tex - single-page cover
% Two-column body: left = title, labels, time, total marks, instructions
%                  right = candidate number boxes + marks table
% A vertical strip runs the full page height on the left edge.
% Both columns are vertically centered.
% ============================================================

\begin{titlepage}
\thispagestyle{cover}
\newgeometry{top=12mm,bottom=12mm,left=0mm,right=12mm}

% Use Helvetica for cover page only
\sffamily

\DrawCornerStrip

% Full-page-height vertical divider line
\noindent\begin{tikzpicture}[remember picture,overlay]
  \draw[black,line width=1pt]
    ([xshift=0.58\linewidth,yshift=-5mm]current page.north west) --
    ([xshift=0.58\linewidth,yshift=20mm]current page.south west);
\end{tikzpicture}

% Reserve vertical space then vertically center both columns
\vspace*{29mm}

\hfill\noindent
\begin{minipage}[c]{0.52\linewidth}
  % ---- Title block ----
  \begin{center}
    {\fontsize{8pt}{10pt}\selectfont
      \CoverAuthority\par}
    \vspace{1.5mm}
    {\fontsize{8pt}{10pt}\selectfont
      \CoverExamName\par}
