    {\fontsize{15pt}{17pt}\selectfont\bfseries \CoverTitle\par}
    \vspace{5mm}
    {\fontsize{11pt}{13pt}\selectfont\bfseries \CoverSubtitle\par}
    \vspace{5mm}
    {\fontsize{10pt}{12pt}\selectfont \CoverLanguageNote\par}
  \end{center}

  \vspace{5mm}

  % ---- Instructions ----
  \hspace{4em}\begin{minipage}[t]{0.85\linewidth}
    {\fontsize{10pt}{12pt}\selectfont\bfseries \CoverInstrHeading\par}
    \vspace{3mm}
    {\fontsize{9.5pt}{11.5pt}\selectfont
    \CoverInstructions}

  \end{minipage}
\end{minipage}%
\begin{minipage}[c]{0.47\linewidth}
  \begin{center}
    {\fontsize{10pt}{10pt}\selectfont\renewcommand{\arraystretch}{2.5}
    \begin{tabular}{|>{\centering\arraybackslash}m{3cm}|*{8}{>{\centering\arraybackslash}m{0.08cm}|}}
      \hline
      \CoverCandidateLabel & & & & & & & & \\
      \hline
    \end{tabular}}
  \end{center}
  \vspace{6mm}
