\question{1}{8} Find the values of the following expressions.

\begin{enumerate}[label=(\alph*),itemsep=2pt]
  \item $\left[(-7.7) - (-6.3)\right] \div (-9.4) - (-2.4) + 4 - 0.4$
  \item $7 - \dfrac{1}{2} \div \left(-2\dfrac{1}{4}\right) + \dfrac{5}{29} - \left(-\dfrac{4}{3}\right)$
\end{enumerate}

\answerlines{10}

\question{2}{5}
\begin{enumerate}[label=(\alph*),itemsep=4pt]
  \item Use directed numbers to write an expression to represent the following and find its value.

  \begin{center}
  ``Divide the sum of positive $9$ and negative $3$ by the product of $2$ and $3$.''
  \end{center}

  \item The height of Tom is $165$ cm and `+1 cm' means $1$ cm taller than Tom. What is the height represented by each of the following directed numbers?
  \begin{enumerate}[label=(\roman*),itemsep=0pt]
    \item $+5$ cm \quad (ii) $-7.5$ cm
  \end{enumerate}
\end{enumerate}

\answerlines{10}

\question{3}{5} Simplify the following expressions.

\begin{enumerate}[label=(\alph*),itemsep=2pt]
  \item $|a - 5| + |3a - 4|$ when $a = -4$
  \item $4 \times (-3) \times 5 - 4 \times (-2) \times 5 \times 6$
\end{enumerate}

\answerlines{10}

\question{7}{8} The following table shows the number of books of $3$ different genres.

\begin{center}
\begin{tabular}{|l|c|}
\hline
\textbf{Genres} & \textbf{Number of books} \\
\hline
Science Fiction & $1824$ \\
Mystery         & $?$ \\
Romance         & $?$ \\
\hline
\end{tabular}
\end{center}

\begin{enumerate}[label=(\alph*),itemsep=4pt]
  \item If there are $8$ libraries in Hong Kong, can all the books be evenly distributed to all the libraries? Explain your answer.

  \answerlines{8}

  \item In the libraries, only books of the same genre can be placed on the same bookshelf, and each bookshelf has the same number of books.
  \begin{enumerate}[label=(\roman*),itemsep=2pt]
    \item What is the maximum number of books placed on the same bookshelf? Explain your answer.

    \answerlines{8}

    \item If each bookshelf contains the number of books in (b)(i), how many bookshelves are needed?

    \answerlines{8}
  \end{enumerate}
\end{enumerate}

\question{8}{8} On a certain day, the temperature at 2 p.m.\ is $25^\circ$C. The temperature changes after each hour from 2 p.m.\ to 5 p.m.\ are recorded as follows. (A decrease in temperature is represented by a negative number.)

\begin{center}
\begin{tabular}{|c|c|}
\hline
\textbf{Time} & \textbf{Temperature change ($^\circ$C)} \\
\hline
2 p.m.\ to 3 p.m. & $-1.4$ \\
3 p.m.\ to 4 p.m. & $+0.6$ \\
4 p.m.\ to 5 p.m. & $-1.2$ \\
\hline
\end{tabular}
\end{center}

\begin{enumerate}[label=(\alph*),itemsep=4pt]
  \item Find the temperatures at
  \begin{enumerate}[label=(\roman*),itemsep=0pt]
    \item 3 p.m.,
    \item 4 p.m.,
    \item 5 p.m.
  \end{enumerate}

  \answerlines{6}

  \item If the temperature at 7 p.m.\ is $22.6^\circ$C and the temperature changes from 5 p.m.\ to 6 p.m.\ and from 6 p.m.\ to 7 p.m.\ are the same, Candy claims that the temperature at 6 p.m.\ is higher than the temperature at 2 p.m.\ Do you agree? Explain your answer.

  \answerlines{8}
\end{enumerate}

\question{9}{8} It is given that $T_n$ is the general term of a sequence.

\begin{enumerate}[label=(\alph*),itemsep=4pt]
  \item Determine what kind of sequence it is.

  \answerlines{4}

  \item The sum of the first $n$ terms of the sequence is given by the following formula.
  \[
  S_n = \sum_{k=1}^{n} T_k = \dfrac{n(n+1)(2n+1)}{6}
  \]
  \begin{enumerate}[label=(\roman*),itemsep=2pt]
    \item Find the values of $S(10)$, $S(19)$ and $S(20)$.

    \answerlines{4}

    \item Hence, find the values of $4 + 16 + 36 + 64 + \cdots + 400$ and $1^3 + 2^3 + 3^3 + \cdots + 19^3$.

    \answerlines{8}
  \end{enumerate}
\end{enumerate}

